from collections import deque
g = {1: [2, 3], 2: [4], 3: [4], 4: []}
d = {1: 0}
q = deque([1])
while q:
    u = q.popleft()
    for v in g[u]:
        if v not in d:
            d[v] = d[u] + 1; q.append(v)
print(d)

import heapq
g = {1: [(2, 7), (3, 2)], 3: [(2, 3)], 2: []}
d = {1: 0}
h = [(0, 1)]
while h:
    du, u = heapq.heappop(h)
    if du > d.get(u, 1e9): continue
    for v, w in g[u]:
        if du + w < d.get(v, 1e9):
            d[v] = du + w; heapq.heappush(h, (d[v], v))
print(d)

